## Why This Is Asked
This question tests understanding of order statistics in dynamic multisets with duplicates and efficient prefix queries—skills fundamental to database indexing and ranking problems.

## Key Concepts
- **Balanced BST with per-node counts and subtree sizes** enables O(log n) operations
- **Handling duplicates via dupCount** avoids unnecessary node creation
- **getRank as a prefix-count query** is analogous to order statistics

## Code Example
```javascript
class Node {
  constructor(key) {
    this.key = key;
    this.dup = 1;
    this.left = null;
    this.right = null;
  }

  get size() {
    return this.dup + (this.left?.size ?? 0) + (this.right?.size ?? 0);
  }
}

class Treap {
  constructor() {
    this.root = null;
  }

  insert(key) {
    this.root = this._insert(this.root, key);
  }

  _insert(node, key) {
    if (!node) return new Node(key);
    if (key === node.key) {
      node.dup++;
    } else if (key < node.key) {
      node.left = this._insert(node.left, key);
    } else {
      node.right = this._insert(node.right, key);
    }
    return node;
  }

  erase(key) {
    this.root = this._erase(this.root, key);
  }

  _erase(node, key) {
    if (!node) return null;
    if (key === node.key) {
      node.dup--;
      if (node.dup === 0) return this._merge(node.left, node.right);
    } else if (key < node.key) {
      node.left = this._erase(node.left, key);
    } else {
      node.right = this._erase(node.right, key);
    }
    return node;
  }

  _merge(left, right) {
    if (!left || !right) return left ?? right;
    // Simplified: in a real Treap, merge by priority
    return this._bstMerge(left, right);
  }

  _bstMerge(left, right) {
    if (!left) return right;
    if (!right) return left;
    const node = left;
    node.right = this._bstMerge(node.right, right);
    return node;
  }

  getRank(v) {
    return this._getRank(this.root, v);
  }

  _getRank(node, v) {
    if (!node) return 0;
    if (v < node.key) {
      return this._getRank(node.left, v);
    }
    const leftSize = node.left?.size ?? 0;
    return leftSize + node.dup + this._getRank(node.right, v);
  }
}
```

## Why This Is Asked
Tests knowledge of a prefix-based data structure with duplicates and two complementary operations: prefix aggregation and k-th element selection within a constrained subtree.

## Key Concepts
- Trie augmented with passCount and endCount per node
- Duplicate handling via endCount
- Prefix-range query via passCount at prefix node
- K-th retrieval via lexicographic traversal using child passCounts

## Code Example
```javascript
class TrieNode {
  constructor() {
    this.children = new Map();
    this.pass = 0;
    this.end = 0;
  }
}
class TrieDict {
  constructor() { this.root = new TrieNode(); }
  insert(word) {
    let p = this.root; p.pass++;
    for (const ch of word) {
      if (!p.children.has(ch)) p.children.set(ch, new TrieNode());
      p = p.children.get(ch); p.pass++;
    }
    p.end++;
  }
  erase(word) {
    if (!this._exists(word)) return;
    let p = this.root; p.pass--;
    for (const ch of word) {
      const nxt = p.children.get(ch); nxt.pass--;
      if (nxt.pass === 0) p.children.delete(ch); else p = nxt;
    }
    p.end--;
  }
  countWithPrefix(prefix) {
    const node = this._getNode(prefix); return node ? node.pass : 0;
  }
  kthWordWithPrefix(prefix, k) {
    const node = this._getNode(prefix); if (!node) return null;
    let res = prefix; let cur = node;
    // If k falls on words exactly equal to prefix
    if (cur.end >= k) return res;
    k -= cur.end;
    while (true) {
      const keys = Array.from(cur.children.keys()).sort();
      for (const c of keys) {
        const child = cur.children.get(c);
        if (child.pass >= k) { res += c; cur = child; if (cur.end >= k) return res; k -= cur.end; break; }
        k -= child.pass;
      } else { return null; }
    }
  }
  _getNode(s) {
    let p = this.root; for (const ch of s) { if (!p.children.has(ch)) return null; p = p.children.get(ch); } return p;
  }
  _exists(word) { const n = this._getNode(word); return !!n && n.end > 0; }
}
```

